"""Applies Career Ops settings to the platform folders generated by `flutter create`."""
import pathlib
import re

SCHEME = 'com.koushiknavuluri.careerpocket'
NAME = 'Career Ops'
root = pathlib.Path(__file__).resolve().parent.parent


def patch(path, fn):
    p = root / path
    if not p.exists():
        print(f'skip (missing): {path}')
        return
    before = p.read_text()
    after = fn(before)
    p.write_text(after)
    print(('patched: ' if after != before else 'unchanged: ') + path)


def gradle(text):
    text = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 26', text)
    text = re.sub(r'minSdkVersion\s+flutter\.minSdkVersion', 'minSdkVersion 26', text)
    if 'appAuthRedirectScheme' not in text:
        line = (f'        manifestPlaceholders["appAuthRedirectScheme"] = "{SCHEME}"\n' if path_is_kts
                else f"        manifestPlaceholders += [appAuthRedirectScheme: '{SCHEME}']\n")
        text = re.sub(r'(defaultConfig\s*\{\n)', r'\1' + line.replace('\\', '\\\\'), text, count=1)
    return text


def manifest(text):
    if 'android.permission.INTERNET' not in text:
        text = text.replace('<application', '<uses-permission android:name="android.permission.INTERNET" />\n    <application', 1)
    if 'android.intent.category.BROWSABLE' not in text:
        browser = ('<intent>\n            <action android:name="android.intent.action.VIEW" />\n'
                   '            <category android:name="android.intent.category.BROWSABLE" />\n'
                   '            <data android:scheme="https" />\n        </intent>\n        ')
        if '<queries>' in text:
            text = text.replace('<queries>\n        ', '<queries>\n        ' + browser, 1)
        else:
            text = text.replace('</manifest>', '    <queries>\n        ' + browser + '</queries>\n</manifest>', 1)
    return re.sub(r'android:label="[^"]*"', f'android:label="{NAME}"', text, count=1)


def plist(text):
    text = re.sub(r'(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)', rf'\g<1>{NAME}\g<2>', text)
    if 'CFBundleURLTypes' not in text:
        block = ('\t<key>CFBundleURLTypes</key>\n\t<array>\n\t\t<dict>\n\t\t\t<key>CFBundleURLSchemes</key>\n'
                 f'\t\t\t<array>\n\t\t\t\t<string>{SCHEME}</string>\n\t\t\t</array>\n\t\t</dict>\n\t</array>\n')
        idx = text.rfind('</dict>')
        text = text[:idx] + block + text[idx:]
    return text


def pbxproj(text):
    return re.sub(r'IPHONEOS_DEPLOYMENT_TARGET = \d+(\.\d+)?;', 'IPHONEOS_DEPLOYMENT_TARGET = 15.0;', text)


path_is_kts = (root / 'android/app/build.gradle.kts').exists()
patch('android/app/build.gradle.kts' if path_is_kts else 'android/app/build.gradle', gradle)
patch('android/app/src/main/AndroidManifest.xml', manifest)
patch('ios/Runner/Info.plist', plist)
patch('ios/Runner.xcodeproj/project.pbxproj', pbxproj)
